191: static char *
192: find_pattern(char *buffer, size_t bufsize, char * pattern, size_t patsize)
193: {
194:     char * result = NULL;
195:     char * p;
196:     char * bp = buffer;
197:     size_t n;
198: 
199:     while ((n = bufsize - (bp - buffer) - patsize) >= 0) {
200:         p = (char *) memchr(bp, pattern[0], n);
201:         if (p == NULL)
202:             break;
203:         if (memcmp(pattern, p, patsize) == 0) {
204:             result = p; /* keep trying - we want the last one */
205:         }
206:         bp = p + 1;
207:     }
208:     return result;
209: }
