211: static char *
212: find_shebang(char * buffer, size_t bufsize)
213: {
214:     FILE * fp = NULL;
215:     errno_t rc;
216:     char * result = NULL;
217:     char * p;
218:     size_t read;
219:     long pos;
220:     __int64 file_size;
221:     __int64 end_cdr_offset = -1;
222:     ENDCDR end_cdr;
223: 
224:     rc = _wfopen_s(&fp, script_path, L"rb");
225:     assert(rc == 0, "Failed to open executable");
226:     fseek(fp, 0, SEEK_END);
227:     file_size = ftell(fp);
228:     pos = (long) (file_size - bufsize);
229:     if (pos < 0)
230:         pos = 0;
231:     fseek(fp, pos, SEEK_SET);
232:     read = fread(buffer, sizeof(char), bufsize, fp);
233:     p = find_pattern(buffer, read, end_cdr_sig, sizeof(end_cdr_sig));
234:     if (p != NULL) {
235:         end_cdr = *((ENDCDR *) p);
236:         end_cdr_offset = pos + (p - buffer);
237:     }
238:     else {
239:         /*
240:          * Try a larger buffer. A comment can only be 64K long, so
241:          * go for the largest size.
242:          */
243:         char * big_buffer = malloc(LARGE_BUFSIZE);
244:         int n = (int) LARGE_BUFSIZE;
245: 
246:         pos = (long) (file_size - n);
247: 
248:         if (pos < 0)
249:             pos = 0;
250:         fseek(fp, pos, SEEK_SET);
251:         read = fread(big_buffer, sizeof(char), n, fp);
252:         p = find_pattern(big_buffer, read, end_cdr_sig, sizeof(end_cdr_sig));
253:         assert(p != NULL, "Unable to find an appended archive.");
254:         end_cdr = *((ENDCDR *) p);
255:         end_cdr_offset = pos + (p - big_buffer);
256:         free(big_buffer);
257:     }
258:     end_cdr_offset -= end_cdr.cdsize + end_cdr.cdoffset;
259:     /*
260:      * end_cdr_offset should now be pointing to the start of the archive.
261:      * However, the "start of the archive" is a little ill-defined, as
262:      * not all means of prepending data to a zipfile handle the central
263:      * directory offset the same way (simple file content appends leave
264:      * it alone, obviously, but the stdlib zipapp and zipfile modules
265:      * reflect the prepended data in the offset).
266:      * We consider two possibilities here:
267:      * 1. end_cdr_offset points to the start of the shebang (zipapp)
268:      * 2. end_cdr_offset points to the end of the shebang (data copy)
269:      * We'll assume the shebang line has no # or ! chars except at the
270:      * beginning, and fits into bufsize (which should be MAX_PATH).
271:      */
272: 
273:     /* Check for case 1 - we are at the start of the shebang */
274:     fseek(fp, (long) end_cdr_offset, SEEK_SET);
275:     read = fread(buffer, sizeof(char), bufsize, fp);
276:     assert(read > 0, "Unable to read from file");
277:     if (memcmp(buffer, "#!", 2) == 0) {
278:         result = buffer;
279:     }
280:     else {
281:         /* We are not at the start, so check backward bufsize bytes */
282:         pos = (long) (end_cdr_offset - bufsize);
283:         if (pos < 0)
284:             pos = 0;
285:         fseek(fp, pos, SEEK_SET);
286:         read = fread(buffer, sizeof(char), bufsize, fp);
287:         assert(read > 0, "Unable to read from file");
288:         p = &buffer[read - 1];
289:         while (p >= buffer) {
290:             if (memcmp(p, "#!", 2) == 0) {
291:                 result = p;
292:                 break;
293:             }
294:             --p;
295:         }
296:     }
297:     fclose(fp);
298:     return result;
