826:     if (!ok) {
827:         // Failed to create process. See if we can find out why.
828:         DWORD err = GetLastError();
829:         wchar_t emessage[MSGSIZE];
830:         FormatMessageW(FORMAT_MESSAGE_FROM_SYSTEM, NULL, err,
831:                        MAKELANGID(LANG_NEUTRAL, SUBLANG_DEFAULT), emessage, MSGSIZE, NULL);
832:         wassert(ok, L"Unable to create process using '%ls': %ls", cmdline, emessage);
833:     }
834:     // Assign the process to the job straight away. See https://github.com/pypa/distlib/issues/175
835:     AssignProcessToJobObject(job, child_process_info.hProcess);
836:     post_spawn_cleanup(si.cbReserved2, si.lpReserved2);
837:     /*
838:      * Control handler setting is now done after process creation because the handler needs access
839:      * to the child_process_info structure, which is populated by the CreateProcessW call above.
840:      */
841:     ok = SetConsoleCtrlHandler((PHANDLER_ROUTINE) control_key_handler, TRUE);
842:     assert(ok, "control handler setting failed");
843: #if !defined(_CONSOLE)
844:     clear_app_starting_state(&child_process_info);
845: #endif
846:     CloseHandle(child_process_info.hThread);
847:     WaitForSingleObjectEx(child_process_info.hProcess, INFINITE, FALSE);
848:     ok = GetExitCodeProcess(child_process_info.hProcess, &rc);
849:     assert(ok, "Failed to get exit code of process");
850:     ExitProcess(rc);
851: }
