853: static wchar_t *
854: find_exe_extension(wchar_t * line) {
855:     wchar_t * p;
856: 
857:     while ((p = StrStrIW(line, L".exe")) != NULL) {
858:         wchar_t c = p[4];
859: 
860:         if ((c == L'\0') || (c == L'"') || iswspace(c))
861:             break;
862:         line = &p[4];
863:     }
864:     return p;
865: }
866: 
867: static wchar_t *
868: find_executable_and_args(wchar_t * line, wchar_t ** argp)
869: {
870:     wchar_t * p = find_exe_extension(line);
871: #if defined(USE_ENVIRONMENT)
872:     wchar_t * q;
873:     int n;
874: #endif
875:     wchar_t * result;
876: 
877: #if !defined(USE_ENVIRONMENT)
878:     assert(p != NULL, "Expected to find a command ending in '.exe' in shebang line: %ls", line);
879:     p += 4; /* skip past the '.exe' */
880:     result = line;
881: #else
882:     if (p != NULL) {
883:         p += 4; /* skip past the '.exe' */
884:         result = line;
885:     }
886:     else {
887:         n = _wcsnicmp(line, L"/usr/bin/env", 12);
888:         assert(n == 0, "Expected to find a command ending in '.exe' in shebang line: %ls", line);
889:         p = line + 12; /* past the '/usr/bin/env' */
890:         assert(*p && iswspace(*p), "Expected to find whitespace after '/usr/bin/env': %ls", line);
891:         do {
892:             ++p;
893:         } while (*p && iswspace(*p));
894:         /* Now, p points to what comes after /usr/bin/env and any following whitespace. */
895:         q = p;
896:         /* Skip past executable name and NUL-terminate it. */
897:         while (*q && !iswspace(*q))
898:             ++q;
899:         if (iswspace(*q))
900:             *q++ = L'\0';
901:         result = find_environment_executable(p);
902:         assert(result != NULL, "Unable to find executable in environment: %ls", line);
903:         p = q; /* point past name of executable in shebang */
904:     }
905: #endif
906:     if (*line == L'"') {
907:         assert(*p == L'"', "Expected terminating double-quote for executable in shebang line: %ls", line);
908:         *p++ = L'\0';
909:         ++line;
910:         ++result;  /* See https://bitbucket.org/pypa/distlib/issues/104 */
911:     }
912:     /* p points just past the executable. It must either be a NUL or whitespace. */
913: #if !defined(SUPPORT_RELATIVE_PATH)
914:     assert(*p != L'"', "Terminating quote without starting quote for executable in shebang line: %ls", line);
915: #else
916:     if (_wcsnicmp(line, RELATIVE_PREFIX, RELATIVE_PREFIX_LENGTH) && (line[RELATIVE_PREFIX_LENGTH] != L'\"')) {
917:         assert(*p != L'"', "Terminating quote without starting quote for executable in shebang line: %ls", line);
918:     }
919: #endif
920:     /* if p is whitespace, make it NUL to truncate 'line', and advance */
921:     if (*p && iswspace(*p))
922:         *p++ = L'\0';
923:     /* Now we can skip the whitespace, having checked that it's there. */
924:     while(*p && iswspace(*p))
925:         ++p;
926:     *argp = p;
927:     return result;
928: }
