930: static int
931: process(int argc, char * argv[])
932: {
933:     wchar_t * cmdline = skip_me(GetCommandLineW());
934:     wchar_t * psp;
935:     size_t len = GetModuleFileNameW(NULL, script_path, MAX_PATH);
936:     FILE *fp = NULL;
937:     char buffer[MAX_PATH];
938:     wchar_t wbuffer[MAX_PATH];
939: #if defined(SUPPORT_RELATIVE_PATH)
940:     wchar_t dbuffer[MAX_PATH];
941:     wchar_t pbuffer[MAX_PATH];
942:     wchar_t * qp;
943:     int prefix_offset;
944: #endif
945:     char *cp;
946:     wchar_t * wcp;
947:     wchar_t * cmdp;
948:     char * p;
949:     wchar_t * wp;
950:     int n;
951: #if !defined(APPENDED_ARCHIVE)
952:     errno_t rc;
953: #endif
954: 
955:     if (script_path[0] != L'\"')
956:         psp = script_path;
957:     else {
958:         psp = &script_path[1];
959:         len -= 2;
960:     }
961:     psp[len] = L'\0';
962: 
963: #if !defined(APPENDED_ARCHIVE)
964:     /* Replace the .exe with -script.py(w) */
965:     wp = wcsstr(psp, L".exe");
966:     assert(wp != NULL, "Failed to find \".exe\" in executable name");
967: 
968:     len = MAX_PATH - (wp - script_path);
969:     assert(len > sizeof(suffix), "Failed to append \"%ls\" suffix", suffix);
970:     wcsncpy_s(wp, len, suffix, sizeof(suffix));
971: #endif
972: #if defined(APPENDED_ARCHIVE)
973:     /* Initialise signature dynamically so that it doesn't appear in
974:      * a stock executable.
975:      */
976:     end_cdr_sig[0] = 0x50;
977: 
978:     p = find_shebang(buffer, MAX_PATH);
979:     assert(p != NULL, "Failed to find shebang");
980: #else
981:     rc = _wfopen_s(&fp, psp, L"rb");
982:     assert(rc == 0, "Failed to open script file '%ls'", psp);
983:     fread(buffer, sizeof(char), MAX_PATH, fp);
984:     fclose(fp);
985:     p = buffer;
986: #endif
987:     cp = find_terminator(p, MAX_PATH);
988:     assert(cp != NULL, "Expected to find terminator in shebang line");
989:     *cp = '\0';
990:     // Decode as UTF-8
991:     n = MultiByteToWideChar(CP_UTF8, MB_ERR_INVALID_CHARS, p, (int) (cp - p), wbuffer, MAX_PATH);
992:     assert(n != 0, "Expected to decode shebang line using UTF-8");
993:     wbuffer[n] = L'\0';
994:     wcp = wbuffer;
995:     while (*wcp && iswspace(*wcp))
996:         ++wcp;
997:     assert(*wcp == L'#', "Expected to find \'#\' at start of shebang line");
998:     ++wcp;
999:     while (*wcp && iswspace(*wcp))
1000:         ++wcp;
1001:     assert(*wcp == L'!', "Expected to find \'!\' following \'#\' in shebang line");
1002:     ++wcp;
1003:     while (*wcp && iswspace(*wcp))
1004:         ++wcp;
1005:     wp = NULL;
1006:     wcp = find_executable_and_args(wcp, &wp);
1007:     assert(wcp != NULL, "Expected to find executable in shebang line");
1008:     assert(wp != NULL, "Expected to find arguments (even if empty) in shebang line");
1009: #if defined(SUPPORT_RELATIVE_PATH)
1010:     /*
1011:        If the executable starts with the relative prefix, resolve the following path
1012:        relative to the launcher's directory.
1013:      */
1014:     prefix_offset = RELATIVE_PREFIX_LENGTH;
1015:     if (!_wcsnicmp(RELATIVE_PREFIX, wcp, prefix_offset)) {
1016:         wcscpy_s(dbuffer, MAX_PATH, script_path);
1017:         PathRemoveFileSpecW(dbuffer);
1018:         if (wcp[prefix_offset] == L'\"') {
1019:             prefix_offset++;
1020:             qp = wcschr(&wcp[prefix_offset], L'\"');
1021:             assert(qp != NULL, "Expected terminating double-quote for executable in shebang line: %ls", wcp);
1022:             *qp = L'\0';
1023:         }
1024:         // The following call appears to canonicalize the path, so no need to
1025:         // worry about doing that
1026:         PathCombineW(pbuffer, dbuffer, &wcp[prefix_offset]);
1027:         wcp = pbuffer;
1028:     }
1029: #endif
1030:      /* 3 spaces + 4 quotes + NUL */
1031:     len = wcslen(wcp) + wcslen(wp) + 8 + wcslen(psp) + wcslen(cmdline);
1032:     cmdp = (wchar_t *) calloc(len, sizeof(wchar_t));
1033:     assert(cmdp != NULL, "Expected to be able to allocate command line memory");
1034:     _snwprintf_s(cmdp, len, len, L"\"%ls\" %ls \"%ls\" %ls", wcp, wp, psp, cmdline);
1035:     run_child(cmdp);  /* never actually returns */
1036:     free(cmdp);
1037:     return 0;
1038: }
